import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/svg.dart';

import '../../../pages/receive_view/addresses/address_card.dart';
import '../../../pages/receive_view/addresses/address_tag_data.dart';
import '../../../pages/receive_view/addresses/address_tag_filter.dart';
import '../../../themes/stack_colors.dart';
import '../../../utilities/assets.dart';
import '../../../utilities/constants.dart';
import '../../../utilities/text_styles.dart';
import '../../../utilities/util.dart';
import '../../../wallets/isar/providers/wallet_info_provider.dart';
import '../../../widgets/icon_widgets/x_icon.dart';
import '../../../widgets/loading_indicator.dart';
import '../../../widgets/rounded_white_container.dart';
import '../../../widgets/stack_text_field.dart';
import '../../../widgets/textfield_icon_button.dart';
import '../desktop_wallet_addresses_view.dart';

class DesktopAddressList extends ConsumerStatefulWidget {
  const DesktopAddressList({
    super.key,
    required this.walletId,
    this.searchHeight,
  });

  final String walletId;
  final double? searchHeight;

  @override
  ConsumerState<DesktopAddressList> createState() => _DesktopAddressListState();
}

class _DesktopAddressListState extends ConsumerState<DesktopAddressList> {
  final bool isDesktop = Util.isDesktop;

  String _searchString = "";
  String? _selectedTag;
  Timer? _searchDebounce;

  late final TextEditingController _searchController;
  final searchFieldFocusNode = FocusNode();

  @override
  void initState() {
    _searchController = TextEditingController();

    super.initState();
  }

  @override
  void dispose() {
    _searchDebounce?.cancel();
    _searchController.dispose();
    searchFieldFocusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final coin = ref.watch(pWalletCoin(widget.walletId));
    final tags = ref
        .watch(walletAddressTagsProvider(widget.walletId))
        .when(
          data: (value) => value,
          error: (_, __) => const <String>[],
          loading: () => const <String>[],
        );
    final selectedTag = reconcileSelectedAddressTag(_selectedTag, tags);
    if (selectedTag != _selectedTag) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _selectedTag != selectedTag) {
          setState(() => _selectedTag = selectedTag);
        }
      });
    }
    final ids = ref.watch(
      filteredWalletAddressIdsProvider(
        WalletAddressFilter(
          walletId: widget.walletId,
          searchTerm: _searchString,
          tag: selectedTag,
        ),
      ),
    );

    return Column(
      children: [
        SizedBox(
          height: widget.searchHeight!,
          child: Center(
            child: ClipRRect(
              borderRadius: BorderRadius.circular(
                Constants.size.circularBorderRadius,
              ),
              child: TextField(
                autocorrect: !isDesktop,
                enableSuggestions: !isDesktop,
                controller: _searchController,
                focusNode: searchFieldFocusNode,
                onChanged: (value) {
                  _searchDebounce?.cancel();
                  setState(() {});
                  _searchDebounce = Timer(
                    const Duration(milliseconds: 250),
                    () {
                      if (mounted) {
                        setState(() => _searchString = value);
                      }
                    },
                  );
                },
                style: isDesktop
                    ? STextStyles.desktopTextExtraSmall(context).copyWith(
                        color: Theme.of(
                          context,
                        ).extension<StackColors>()!.textFieldActiveText,
                        height: 1.8,
                      )
                    : STextStyles.field(context),
                decoration:
                    standardInputDecoration(
                      "Search...",
                      searchFieldFocusNode,
                      context,
                      desktopMed: isDesktop,
                    ).copyWith(
                      prefixIcon: Padding(
                        padding: EdgeInsets.symmetric(
                          horizontal: isDesktop ? 12 : 10,
                          vertical: isDesktop ? 18 : 16,
                        ),
                        child: SvgPicture.asset(
                          Assets.svg.search,
                          width: isDesktop ? 20 : 16,
                          height: isDesktop ? 20 : 16,
                        ),
                      ),
                      suffixIcon: _searchController.text.isNotEmpty
                          ? Padding(
                              padding: const EdgeInsets.only(right: 0),
                              child: UnconstrainedBox(
                                child: Row(
                                  children: [
                                    TextFieldIconButton(
                                      child: const XIcon(),
                                      onTap: () async {
                                        _searchDebounce?.cancel();
                                        setState(() {
                                          _searchController.text = "";
                                          _searchString = "";
                                        });
                                      },
                                    ),
                                  ],
                                ),
                              ),
                            )
                          : null,
                    ),
              ),
            ),
          ),
        ),
        if (tags.isNotEmpty) const SizedBox(height: 16),
        if (tags.isNotEmpty)
          AddressTagFilter(
            tags: tags,
            selectedTag: selectedTag,
            onSelected: (tag) => setState(() => _selectedTag = tag),
          ),
        const SizedBox(height: 20),
        Expanded(
          child: RoundedWhiteContainer(
            padding: EdgeInsets.zero,
            child: ids.when(
              data: (addressIds) => ListView.separated(
                shrinkWrap: true,
                itemCount: addressIds.length,
                separatorBuilder: (_, __) => Container(
                  height: 1,
                  color: Theme.of(
                    context,
                  ).extension<StackColors>()!.backgroundAppBar,
                ),
                itemBuilder: (_, index) => Padding(
                  padding: const EdgeInsets.all(4),
                  child: AddressCard(
                    key: Key("addressCardDesktop_key_${addressIds[index]}"),
                    walletId: widget.walletId,
                    addressId: addressIds[index],
                    coin: coin,
                    onPressed: () {
                      ref.read(desktopSelectedAddressId.state).state =
                          addressIds[index];
                    },
                  ),
                ),
              ),
              error: (_, __) => Center(
                child: Text(
                  "Couldn't load addresses",
                  style: STextStyles.w500_14(context),
                ),
              ),
              loading: () => const Center(
                child: LoadingIndicator(height: 200, width: 200),
              ),
            ),
          ),
        ),
      ],
    );
  }
}
